function setup(){
 let tasks=[];try{const saved=JSON.parse(localStorage.getItem('tasks')||'[]');if(Array.isArray(saved))tasks=saved.filter(t=>typeof t.title==='string'&&typeof t.done==='boolean')}catch{}
 const input=document.querySelector('#new-task'),list=document.querySelector('#tasks');
 function save(){localStorage.setItem('tasks',JSON.stringify(tasks))}
 function render(){list.textContent='';for(const [index,t]of tasks.entries()){
  const li=document.createElement('li');li.className='task';const title=document.createElement('span');title.className='task-title';title.textContent=t.title;
  const toggle=document.createElement('button');toggle.className='toggle';toggle.textContent=t.done?'أعد فتحها':'تم';toggle.addEventListener('click',()=>{t.done=!t.done;save();render()});
  const remove=document.createElement('button');remove.className='remove';remove.textContent='احذف';remove.addEventListener('click',()=>{tasks.splice(index,1);save();render()});li.append(title,toggle,remove);list.append(li)
 }document.querySelector('#completed').textContent=String(tasks.filter(t=>t.done).length);document.querySelector('#remaining').textContent=String(tasks.filter(t=>!t.done).length)}
 document.querySelector('#add-task').addEventListener('click',()=>{const title=input.value.trim();if(!title)return;tasks.push({title,done:false});input.value='';save();render()});render();
}

