function setup(){
 let expenses=[];try{const raw=JSON.parse(localStorage.getItem('expenses')||'[]');if(Array.isArray(raw))expenses=raw.filter(x=>typeof x.title==='string'&&Number.isFinite(x.amount)&&x.amount>0)}catch{}
 const title=document.querySelector('#expense-title'),amount=document.querySelector('#expense-amount'),budget=document.querySelector('#budget'),list=document.querySelector('#expenses');
 function save(){localStorage.setItem('expenses',JSON.stringify(expenses))}
 function render(){list.textContent='';for(const[index,e]of expenses.entries()){const li=document.createElement('li');li.className='expense';const label=document.createElement('span');label.className='expense-title';label.textContent=e.title;const remove=document.createElement('button');remove.className='remove';remove.textContent='حذف';remove.addEventListener('click',()=>{expenses.splice(index,1);save();render()});li.append(label,document.createTextNode(' '+e.amount.toFixed(2)+' '),remove);list.append(li)}const total=expenses.reduce((sum,e)=>sum+e.amount,0);document.querySelector('#total').textContent=total.toFixed(2);document.querySelector('#count').textContent=String(expenses.length);const limit=Number(budget.value);document.querySelector('#remaining-budget').textContent=(Number.isFinite(limit)?limit-total:0).toFixed(2)}
 document.querySelector('#add-expense').addEventListener('click',()=>{const name=title.value.trim(),value=Number(amount.value);if(!name||!amount.value.trim()||!Number.isFinite(value)||value<=0)return;expenses.push({title:name,amount:value});title.value='';amount.value='';save();render()});budget.addEventListener('input',render);render();
}

